<script setup lang="ts">

import {can} from './session'
import {ref,reactive,onMounted,watch} from 'vue'
import {api,session} from './session'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useTableWidths} from './tableWidths'
const props=defineProps<{kind:'declaration'|'clearance'}>(),widths=useTableWidths('CustomsCodes'),rows=ref<any[]>([]),q=ref(''),code=ref(''),page=ref(1),pageSize=ref(25),total=ref(0),busy=ref(false),dialog=ref(false),editing=ref<any>(),form=reactive<any>({}),fileInput=ref<HTMLInputElement>()
async function load(){busy.value=true;try{const d=await api('/customs/codes/'+props.kind+'?'+new URLSearchParams({name:q.value,hs_code:code.value,page:String(page.value),page_size:String(pageSize.value)}));rows.value=d.rows;total.value=d.total}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
watch(()=>props.kind,()=>{q.value='';code.value='';page.value=1;dialog.value=false;load()});onMounted(load)
function edit(row?:any){editing.value=row;Object.assign(form,{name:row?.name||'',hs_code:row?.hs_code||'',tax_rate:row?Number(row.tax_rate):0,declaration_elements:row?.declaration_elements||'',revision:row?.revision});dialog.value=true}
async function save(){busy.value=true;try{await api('/customs/codes/'+props.kind+(editing.value?'/'+editing.value.id:''),form);dialog.value=false;await load();ElMessage.success('已保存')}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function remove(row:any){try{await ElMessageBox.confirm('删除此编码？已保存到产品的资料会保留。','删除编码',{type:'warning'});await api(`/customs/codes/${props.kind}/${row.id}/delete`,{revision:row.revision});await load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;busy.value=true;try{if(file.size>15*1024*1024)throw Error('文件不能超过15MB');const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));const d=await api('/customs/import/'+props.kind,{filename:file.name,content:btoa(raw)});ElMessage.success(`已新增 ${d.added} 条，更新 ${d.updated} 条`);await load()}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false;input.value=''}}
</script>
<template><section class="codes-panel"><div class="code-tools"><el-input v-model="q" clearable placeholder="搜索商品名称" @keyup.enter="page=1;load()"/><el-input v-model="code" clearable placeholder="搜索 HSCODE 编码" @keyup.enter="page=1;load()"/><el-button type="primary" @click="page=1;load()">查询</el-button><el-button @click="q='';code='';page=1;load()">重置</el-button><el-button @click="load">刷新</el-button><template v-if="can('settings.'+props.kind,'operate')"><el-button type="primary" @click="edit()">新增编码</el-button><el-button :loading="busy" @click="fileInput?.click()">Excel / CSV 导入</el-button><a :href="'/api/customs/import-template?kind='+kind">下载导入模板</a><input ref="fileInput" type="file" accept=".xlsx,.csv" hidden @change="upload"/></template><TableReset :table-key="'CustomsCodes/'+kind"/></div><p>导入列：商品名称、HSCODE、税率{{kind==='declaration'?'、申报要素（选填）':''}}。HSCODE 使用文本格式；税率填百分数，例如 20 表示 20%。相同名称和编码会更新税率。</p><template v-if="true"><el-table :data-width-key="'CustomsCodes/'+kind"    :data="rows" v-loading="busy" border @header-dragend="(w:number,_:number,c:any)=>widths.resize(kind,w,c)"><el-table-column  :width="widths.width(kind,'name',420)" prop="name" label="商品名称" column-key="name" /><el-table-column  :width="widths.width(kind,'code',220)" prop="hs_code" label="HSCODE" column-key="code" /><el-table-column  :width="widths.width(kind,'tax',160)" label="税率（%）" column-key="tax"  align="center"><template #default="{row}">{{row.tax_rate}}</template></el-table-column><el-table-column v-if="kind==='declaration'" prop="declaration_elements" label="申报要素" column-key="elements" :width="widths.width(kind,'elements',360)" show-overflow-tooltip/><el-table-column :column-key="'column-4'" :width="widths.width(kind,'column-4','160')" v-if="can('settings.'+props.kind,'operate')" label="操作" fixed="right" ><template #default="{row}"><el-button type="primary" link @click="edit(row)">编辑</el-button><el-button type="danger" link @click="remove(row)">删除</el-button></template></el-table-column></el-table></template><AppPagination v-model:current-page="page" :total="total" @change="load" v-model:page-size="pageSize"/><el-dialog v-model="dialog" :title="editing?'编辑编码':'新增编码'" width="520px"><el-form label-position="top"><el-form-item label="商品名称"><el-input v-model="form.name" maxlength="500"/></el-form-item><el-form-item label="HSCODE"><el-input v-model="form.hs_code" maxlength="30"/></el-form-item><el-form-item label="税率（%）"><el-input-number v-model="form.tax_rate" :min="0" :max="100" :precision="4"/></el-form-item><el-form-item v-if="kind==='declaration'" label="申报要素"><el-input v-model="form.declaration_elements" type="textarea" :rows="5" maxlength="10000"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog></section></template>
<style scoped>.code-tools{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}.code-tools .el-input{width:260px}.code-tools a{color:#227660;font-size:13px}.codes-panel p{font-size:12px;color:#7b8d83}.el-pagination{margin-top:16px}</style>
